                self.pos += 1
                start_type: Type[object] = InternalRuleDefChar
                if src[self.pos] == "^":
                    self.pos += 1
                    start_type = InternalRuleDefCharNot
                last_sym_start = len(out_elements)
                while src[self.pos] != "]":
                    self.check_duration()
                    type_of_rule: Type[object] = (
                        InternalRuleDefCharAlt
                        if last_sym_start < len(out_elements)
                        else start_type
                    )
                    startchar_value, inc_pos = parse_char(src, self.pos)
                    self.pos += inc_pos
                    out_elements.append(
                        get_out_elements(type_of_rule, startchar_value),
