import ast, pathlib, sys
for p in sorted(pathlib.Path('gbnf').rglob('*.py')):
    tree = ast.parse(p.read_text())
    src = p.read_text()
    imported = set()
    for node in ast.walk(tree):
        if isinstance(node, ast.ImportFrom) or isinstance(node, ast.Import):
            for a in node.names:
                name = (a.asname or a.name).split('.')[0]
                imported.add(name)
    body = "\n".join(l for l in src.splitlines() if not l.strip().startswith(('import ','from ')))
    unused = [n for n in imported if n not in body and f'"{n}"' not in src]
    if unused:
        print(p, sorted(unused))
